// Class 11 Business Studies practice bank, part 2: Social Responsibility and Business Ethics, Sources of Business Finance, Small Business and Entrepreneurship, Internal Trade, International Business.
StudyData.addPractice(11, "business", {
  "social-responsibility-and-business-ethics": {
    mcq: [
      { q: "Obeying the laws of the land, such as paying taxes and following labour laws, is which kind of responsibility of business?", options: ["Economic", "Legal", "Ethical", "Discretionary"], answer: 1, explain: "Legal responsibility means obeying the laws of the land. It is limited to what the law requires.", level: 1 },
      { q: "Under the Companies Act, 2013, a company covered by Section 135 must spend on CSR at least:", options: ["5% of the net profit of the last year", "2% of the average net profit of the three immediately preceding financial years", "2% of the turnover of the last year", "10% of the net worth"], answer: 1, explain: "The minimum CSR spend is 2% of the average net profit of the three immediately preceding financial years.", level: 1 },
      { q: "Dumping of toxic industrial waste on open ground causes:", options: ["Air pollution", "Water pollution", "Noise pollution", "Land pollution"], answer: 3, explain: "Dumping of toxic waste pollutes land. Smoke and emissions cause air pollution, and chemical waste in rivers causes water pollution.", level: 1 },
      { q: "Which of the following is an element of business ethics?", options: ["Maximising selling price", "Avoiding compliance mechanisms", "Limiting employee participation", "Publication of a code"], answer: 3, explain: "The elements are top management commitment, publication of a code, compliance mechanisms, involving employees at all levels and measuring results.", level: 1 },
      { q: "Which of the following is an argument AGAINST social responsibility of business?", options: ["Avoidance of government regulation", "Long-term interest of the firm", "Violation of profit maximisation", "Maintenance of society"], answer: 2, explain: "Spending on social causes may reduce profits, so critics say it violates the profit-maximisation objective. The others are arguments in favour.", level: 1 },

      { q: "Vrindavan Paints runs a free evening coaching centre for children of nearby villages. No law requires it to do so. This is an example of:", options: ["Economic responsibility", "Legal responsibility", "Discretionary responsibility", "Compliance with Section 135"], answer: 2, explain: "A purely voluntary act like helping the community is a discretionary responsibility.", level: 2 },
      {
        q: "Assertion (A): A firm that obeys all laws has fulfilled all its social responsibilities.\nReason (R): Social responsibility is voluntary and goes beyond what the law requires.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 3, explain: "A is false: social responsibility is broader than legal responsibility. R is true and shows why obeying the law is not enough.", level: 2, keepOrder: true
      },
      { q: "Gokul Dairy adds water to its milk to reduce costs. Towards which group is it failing in its responsibility, and in what way?", options: ["Workers: not giving fair wages", "Consumers: adulteration instead of the right quality", "Shareholders: not giving regular information", "Government: not paying taxes honestly"], answer: 1, explain: "Consumers are entitled to the right quality and no adulteration. Adding water to milk violates this.", level: 2 },
      { q: "A company raises its prices by 3% to pay for its social welfare programmes. Which argument against social responsibility does this reflect?", options: ["Lack of broad public support", "Lack of social skills", "Burden on consumers", "Violation of profit maximisation"], answer: 2, explain: "When the cost of social activities is passed on through higher prices, consumers bear the burden.", level: 2 },
      { q: "Using the CSR limits in the content, which of the following companies is covered by Section 135?", options: ["Net worth ₹400 crore, turnover ₹900 crore, net profit ₹4 crore", "Net worth ₹300 crore, turnover ₹700 crore, net profit ₹5 crore", "Net worth ₹450 crore, turnover ₹950 crore, net profit ₹3 crore", "Net worth ₹499 crore, turnover ₹999 crore, net profit ₹4.9 crore"], answer: 1, explain: "A company is covered if net worth is ₹500 crore or more, OR turnover is ₹1,000 crore or more, OR net profit is ₹5 crore or more. Only option B meets one limit (net profit ₹5 crore).", keepOrder: true, level: 2 },

      { q: "A company's net profits in the three preceding financial years were ₹6 crore, ₹9 crore and ₹12 crore. Its minimum CSR spend is:", options: ["₹12 lakh", "₹24 lakh", "₹18 lakh", "₹54 lakh"], answer: 2, explain: "Average net profit = (6 + 9 + 12) ÷ 3 = ₹9 crore. 2% of ₹9 crore = ₹0.18 crore = ₹18 lakh.", level: 3 },
      {
        q: "Assertion (A): Pollution control is in the long-term interest of a business.\nReason (R): It reduces the risk of legal liability, saves costs and improves the public image of the firm.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "The benefits listed in R (less legal risk, saved costs, better image) are exactly why pollution control serves the firm's long-term interest.", level: 3, keepOrder: true
      },
      { q: "Sunrise Steels has published a code of conduct and appointed a compliance officer, but its top management openly ignores violations of the code. Which element of business ethics is missing?", options: ["Publication of a code", "Establishment of compliance mechanisms", "Top management commitment", "Measuring results"], answer: 2, explain: "A code and compliance officer exist, but without the commitment of top management the code is not taken seriously.", level: 3 },
      { q: "Which of the following is an ethical responsibility but is not required by any law?", options: ["Paying income tax honestly", "Producing goods that society wants and selling them at a profit", "Avoiding an advertisement that hurts religious sentiments", "Donating to flood victims"], answer: 2, explain: "Behaving as society expects even where no law requires it, such as respecting religious sentiments in advertisements, is ethical responsibility. Paying tax is legal, selling at a profit is economic, and donating is discretionary.", level: 3 }
    ],
    written: [
      { q: "Define social responsibility of business.", a: "Social responsibility is the obligation of business to pursue policies, make decisions and follow actions that are desirable in terms of the objectives and values of society.", marks: 1 },
      { q: "Name the four kinds of social responsibility.", a: "Economic, legal, ethical and discretionary responsibility.", marks: 1 },
      { q: "State any two arguments against social responsibility of business.", a: "1. It violates the profit-maximisation objective of business.\n2. It is a burden on consumers, who have to pay higher prices. (Also: businessmen lack social skills; lack of broad public support.)", marks: 2 },
      { q: "Distinguish between legal responsibility and discretionary responsibility.", a: "1. Nature: legal responsibility is compulsory, as it means obeying the laws of the land; discretionary responsibility is purely voluntary.\n2. Example: paying taxes honestly is legal responsibility; donating to schools or helping flood victims is discretionary responsibility.", marks: 2 },
      { q: "Explain any three responsibilities of a business towards consumers.", a: "1. Right quality at the right price: goods should be of promised quality and fairly priced.\n2. No adulteration and honest advertising: consumers should not be cheated by mixing or misleading claims.\n3. After-sales service and attention to complaints: consumers' problems should be resolved promptly.", marks: 3 },
      { q: "Explain the different kinds of pollution caused by business.", a: "1. Air pollution: smoke and vehicle emissions from factories and transport.\n2. Water pollution: discharge of chemical and industrial waste into rivers and other water bodies.\n3. Land pollution: dumping of toxic waste on land. (Noise pollution from machines and vehicles is a fourth kind.)", marks: 3 },
      { q: "Explain the CSR provisions of Section 135 of the Companies Act, 2013.", a: "1. Section 135 makes Corporate Social Responsibility compulsory for large companies.\n2. It applies to a company with net worth of ₹500 crore or more, or turnover of ₹1,000 crore or more, or net profit of ₹5 crore or more in the preceding financial year.\n3. Such a company must spend at least 2% of its average net profit of the three immediately preceding financial years on CSR activities such as eradicating hunger and poverty, promoting education and health, gender equality and environmental sustainability.", marks: 3 },
      { q: "Explain any five arguments in favour of social responsibility of business.", a: "1. Justification for existence and growth: society gives business its right to exist, so business should serve society.\n2. Long-term interest of the firm: a good public image helps the firm in the long run.\n3. Avoidance of government regulation: firms that act responsibly voluntarily reduce the need for laws and controls.\n4. Business has resources: money and managerial talent can be used to solve social problems.\n5. Problems into opportunities: social problems can be turned into business opportunities. (Also: maintenance of society; a better environment for doing business; business has itself created some social problems such as pollution.)", marks: 5 },
      { q: "Explain the elements of business ethics.", a: "1. Top management commitment: top managers must set the example and show by their behaviour that ethics matter.\n2. Publication of a 'code': a written code of conduct that tells employees what is expected of them.\n3. Establishment of compliance mechanisms: systems and people to check that the code is followed and to deal with violations.\n4. Involving employees at all levels: employees must understand and take part in ethical practices.\n5. Measuring results: the working of the ethics programme is checked regularly, and improvements are made.", marks: 5 },
      { q: "Case study: Mehta Cement Ltd has a net worth of ₹600 crore and a turnover of ₹900 crore. Its net profits in the last three financial years were ₹40 crore, ₹50 crore and ₹60 crore. The company dumps fly ash on open land near a village, and villagers complain of health problems.\n(i) Is CSR compulsory for Mehta Cement? Give the reason.\n(ii) Calculate the minimum amount it must spend on CSR.\n(iii) Name the type of pollution shown and the group towards which the company is failing in its responsibility.", a: "(i) Yes. Under Section 135 of the Companies Act, 2013, CSR is compulsory for a company whose net worth is ₹500 crore or more (or turnover ₹1,000 crore or more, or net profit ₹5 crore or more). Mehta Cement's net worth of ₹600 crore meets this.\n(ii) Average net profit = (40 + 50 + 60) ÷ 3 = ₹50 crore. Minimum CSR spend = 2% of ₹50 crore = ₹1 crore.\n(iii) Land pollution, caused by dumping fly ash on open land. The company is failing in its responsibility towards the government and community, which includes protecting the environment.", marks: 4, type: "case" }
    ]
  },
  "sources-of-business-finance": {
    mcq: [
      { q: "Money needed to buy land, buildings and machinery is called:", options: ["Working capital", "Fixed capital", "Trade credit", "Retained earnings"], answer: 1, explain: "Fixed capital is needed for long-term assets such as land, buildings and machinery. Working capital meets day-to-day needs.", level: 1 },
      { q: "Which of the following is an owners' fund?", options: ["Debentures", "Public deposits", "Retained earnings", "Trade credit"], answer: 2, explain: "Owners' funds are equity shares, preference shares and retained earnings. The others are borrowed funds.", level: 1 },
      { q: "Debenture holders of a company are its:", options: ["Owners", "Creditors", "Directors", "Equity shareholders"], answer: 1, explain: "A debenture is an acknowledgement of debt, so debenture holders are creditors of the company.", level: 1 },
      { q: "A short-term source of finance is one that is required for a period of:", options: ["more than 5 years", "1 to 5 years", "more than 10 years", "up to 1 year"], answer: 3, explain: "Short-term finance is for up to 1 year, medium-term for 1 to 5 years and long-term for more than 5 years.", level: 1 },
      { q: "Commercial paper is:", options: ["a secured loan from a bank", "an unsecured promissory note issued by a creditworthy company", "a receipt issued abroad against shares", "a share with a fixed rate of dividend"], answer: 1, explain: "Commercial paper is an unsecured promissory note issued by large, creditworthy companies to raise short-term funds.", level: 1 },

      { q: "Kaveri Textiles uses a weaving machine owned by a finance company and pays it fixed monthly rentals. Ownership of the machine stays with the finance company. This source of finance is:", options: ["Factoring", "Lease financing", "Public deposits", "Commercial paper"], answer: 1, explain: "In lease financing the lessor lets the lessee use an asset for periodic lease rentals while ownership remains with the lessor.", level: 2 },
      {
        q: "Assertion (A): Retained earnings are an internal source of finance.\nReason (R): Equity shareholders have voting rights.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 1, explain: "Both statements are true. Retained earnings come from the firm's own profits, so they are internal. Voting rights of equity shareholders do not explain why they are internal.", level: 2, keepOrder: true
      },
      { q: "Hari Flour Mill buys wheat from a supplier who allows payment after 30 days. The amount due appears in its books as sundry creditors. This source of finance is:", options: ["Trade credit", "Inter corporate deposit", "Public deposit", "Commercial paper"], answer: 0, explain: "Credit given by one trader to another at the time of buying goods is trade credit, shown as sundry creditors or accounts payable.", level: 2 },
      { q: "A preference share on which the unpaid dividend of a year is carried forward and paid later out of future profits is called:", options: ["Participating preference share", "Convertible preference share", "Non-cumulative preference share", "Cumulative preference share"], answer: 3, explain: "Cumulative preference shares allow unpaid dividend to accumulate and be paid when profits are available.", level: 2 },
      { q: "Holders of a Global Depository Receipt (GDR) of an Indian company:", options: ["get dividends but have no voting rights", "get voting rights but no dividend", "get both dividends and voting rights", "get a fixed rate of interest only"], answer: 0, explain: "GDR holders receive dividends but have no voting rights.", level: 2 },

      { q: "Simran Handicrafts sells goods on credit. A financial firm collects its debts, discounts its bills and supplies credit information about its customers. This service is:", options: ["Lease financing", "Trade credit", "Factoring", "Commercial paper"], answer: 2, explain: "A factor collects the firm's debts, discounts bills and gives credit information about customers. This is factoring.", level: 3 },
      {
        q: "Assertion (A): For a profitable company, debentures are usually a cheaper source of finance than preference shares.\nReason (R): Interest on debentures is a charge on profit and is tax-deductible, while preference dividend is not.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "Because debenture interest is tax-deductible and preference dividend is not, the effective cost of debentures is lower. R explains A.", level: 3, keepOrder: true
      },
      { q: "A profitable firm needs long-term funds. It does not want to dilute control, and it does not want a fixed burden of interest or dividend. Which source suits it best?", options: ["Equity shares", "Debentures", "Preference shares", "Retained earnings"], answer: 3, explain: "Retained earnings need no new shares (so no dilution of control) and carry no explicit cost or fixed payment. Equity shares dilute control, and debentures and preference shares carry fixed payments.", level: 3 },
      { q: "Which of the following lists contains only internal sources of funds?", options: ["Retained earnings, collection of receivables, disposal of surplus stock", "Retained earnings, debentures, trade credit", "Collection of receivables, equity shares, public deposits", "Disposal of surplus stock, bank loans, ICDs"], answer: 0, explain: "Internal sources are generated within the business: retained earnings, collection of receivables and disposal of surplus stock. The rest are external.", level: 3 }
    ],
    written: [
      { q: "What is meant by trade credit?", a: "Trade credit is credit given by one trader to another when goods are bought. It appears in the books as sundry creditors or accounts payable.", marks: 1 },
      { q: "Define a debenture.", a: "A debenture is an acknowledgement of debt by a company. Debenture holders are creditors and receive a fixed rate of interest whether or not there is profit.", marks: 1 },
      { q: "State any two merits of retained earnings.", a: "1. It carries no explicit cost and does not dilute the control of existing shareholders.\n2. It is a permanent source that adds to the credibility of the company and its capacity to absorb losses.", marks: 2 },
      { q: "Distinguish between GDR and ADR.", a: "1. GDR: a receipt issued abroad in foreign currency against shares of an Indian company, listed and traded on a foreign stock exchange; holders get dividends but no voting rights.\n2. ADR: a depository receipt issued in the USA, which only American citizens can buy and trade.", marks: 2 },
      { q: "Distinguish between equity shares and preference shares on any three points.", a: "1. Voting rights: equity shareholders have voting rights; preference shareholders usually have none, except on matters directly affecting their rights.\n2. Dividend: equity shareholders get dividend only after preference shareholders, and the rate is not fixed; preference shareholders get a fixed rate of dividend.\n3. Repayment on winding up: preference shareholders are repaid before equity shareholders; equity capital is repaid last, so equity bears the highest risk.", marks: 3 },
      { q: "Explain any three short-term sources of finance.", a: "1. Trade credit: credit given by one trader to another on buying goods, shown as sundry creditors.\n2. Factoring: a factor collects the firm's debts, discounts its bills and gives credit information about customers.\n3. Commercial paper: an unsecured promissory note issued by large, creditworthy companies to raise short-term funds. (Others: inter corporate deposits, bank loans and cash credit.)", marks: 3 },
      { q: "Classify business finance on the basis of period and give one source for each category.", a: "1. Long-term (more than 5 years): e.g. equity shares, debentures, loans from financial institutions.\n2. Medium-term (1 to 5 years): e.g. a term loan from a commercial bank that is repayable within this period.\n3. Short-term (up to 1 year): e.g. trade credit, commercial paper, factoring.", marks: 3 },
      { q: "Explain any five factors that affect the choice of a source of business finance.", a: "1. Cost: the cost of raising and of servicing the funds should be low.\n2. Risk: borrowed funds carry fixed payments and so raise the financial risk, while owners' funds carry less risk.\n3. Control: issuing equity shares dilutes the control of existing owners, while debentures and loans do not.\n4. Tax benefits: interest on debentures and loans is tax-deductible, so such sources are cheaper after tax.\n5. Flexibility and purpose/time period: the source should match the need and the period for which funds are required. (Also: financial strength, form of organisation, effect on creditworthiness.)", marks: 5 },
      { q: "Explain the merits and limitations of equity shares as a source of finance.", a: "Merits:\n1. No fixed burden: the company need not pay a fixed rate of dividend.\n2. Permanent capital: it is repaid only on winding up.\n3. It adds to the creditworthiness of the company.\n4. No charge on assets: assets can be kept free for raising loans.\nLimitations:\n1. Costly to raise.\n2. Dilution of control when new shares are issued.\n3. Many formalities have to be completed.\n4. Not attractive to investors who want a steady income.", marks: 5 },
      { q: "Case study: Lakshmi Spices Ltd needs ₹80 lakh for a new packing unit and ₹5 lakh to pay for raw material for two months. For the raw material it plans to buy on 30 days' credit from its suppliers. For the unit it is considering issuing new equity shares, but the promoters fear losing control of the company. The directors suggest issuing debentures instead, as interest is tax-deductible.\n(i) Classify the two needs as fixed or working capital.\n(ii) Name the short-term source for raw material.\n(iii) Which factors in choosing a source of finance are shown in the discussion on equity shares and debentures?", a: "(i) The ₹80 lakh needed for the packing unit is fixed capital (long-term asset). The ₹5 lakh for raw material is working capital (day-to-day need).\n(ii) Trade credit: buying raw material on 30 days' credit from suppliers.\n(iii) Control: the promoters fear dilution of control if equity shares are issued. Tax benefits: debenture interest is tax-deductible. (Cost and risk also arise, since debentures carry a fixed interest burden.)", marks: 4, type: "case" }
    ]
  },
  "small-business-and-entrepreneurship": {
    mcq: [
      { q: "Micro, small and medium enterprises in India are defined under the:", options: ["Companies Act, 2013", "MSMED Act, 2006", "Consumer Protection Act, 2019", "Startup India Act, 2016"], answer: 1, explain: "MSMEs are defined under the Micro, Small and Medium Enterprises Development (MSMED) Act, 2006.", level: 1 },
      { q: "The National Small Industries Corporation (NSIC) was set up in:", options: ["1955", "1978", "1982", "1990"], answer: 0, explain: "NSIC was set up in 1955. DICs began in 1978, NABARD in 1982 and SIDBI in 1990.", level: 1 },
      { q: "District Industries Centres (DICs) provide:", options: ["a single window at the district level for all services needed to set up small industries", "foreign exchange to exporters", "loans only to large companies", "licences for patents"], answer: 0, explain: "DICs give a single window at the district level for all services and support needed to set up small, tiny and village industries.", level: 1 },
      { q: "A person who sets up his or her own business is called a(n):", options: ["Investor", "Employee", "Entrepreneur", "Professional"], answer: 2, explain: "Entrepreneurship is the process of setting up one's own business; the person is the entrepreneur.", level: 1 },
      { q: "Startup India was launched on:", options: ["1 July 2017", "1 January 1995", "1 May 1978", "16 January 2016"], answer: 3, explain: "Startup India was launched on 16 January 2016 to build an ecosystem for startups.", level: 1 },

      { q: "Meena weaves cloth on a handloom at home with the help of her family, using local raw materials and simple tools with very little capital. Her enterprise is a:", options: ["Departmental store", "Medium enterprise", "Village and cottage industry", "Venture-capital-funded startup"], answer: 2, explain: "Family labour, local skills and raw materials, simple tools, small capital and working from home are features of village and cottage industries.", level: 2 },
      {
        q: "Assertion (A): Small businesses support balanced regional development.\nReason (R): They can be set up in villages and small towns.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "Because small units can be located in villages and small towns, industry spreads to backward areas. R explains A.", level: 2, keepOrder: true
      },
      { q: "Nabha Fabrics has investment in plant and machinery of ₹8 crore and an annual turnover of ₹40 crore. Under the 2020 limits, it is a:", options: ["Micro enterprise", "Small enterprise", "Medium enterprise", "Large enterprise"], answer: 1, explain: "The 2020 limit for a small enterprise is up to ₹10 crore investment and ₹50 crore turnover. Both figures are above the micro limits (₹1 crore and ₹5 crore) and within the small limits.", level: 2 },
      { q: "Rohan starts his bakery with his own savings and the money he earns from his first sales, without any outside investor. This way of funding is called:", options: ["Crowdfunding", "Bootstrapping", "Venture capital", "Angel investment"], answer: 1, explain: "Bootstrapping means growing a business with the founder's own savings and early revenue.", level: 2 },
      { q: "Darjeeling Tea, India's first product to get this kind of protection, is an example of a:", options: ["Patent", "Copyright", "Trademark", "Geographical indication"], answer: 3, explain: "A geographical indication marks goods whose qualities come from their region. Darjeeling Tea was India's first GI.", level: 2 },

      { q: "A retired engineer invests ₹50 lakh of her own money in a promising early-stage startup in exchange for a share of ownership. She is a(n):", options: ["Angel investor", "Crowdfunder", "Lessor", "Factor"], answer: 0, explain: "Angel investors are wealthy individuals who invest in early-stage startups for a share of ownership.", level: 3 },
      {
        q: "Assertion (A): Village and cottage industries need large capital and modern machinery.\nReason (R): They use family labour and local skills.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 3, explain: "A is false: these industries use simple tools and small capital. R is true.", level: 3, keepOrder: true
      },
      { q: "Using the limits introduced from April 2025, an enterprise with investment of ₹30 crore and turnover of ₹120 crore is classified as:", options: ["Micro", "Small", "Medium", "Large"], answer: 2, explain: "From April 2025 the small limits are ₹25 crore / ₹100 crore, so this enterprise exceeds them. The medium limits are ₹125 crore / ₹500 crore, which it is within.", level: 3 },
      { q: "Which sequence lists these institutions in the order of their setting up (earliest first)?", options: ["DIC, NSIC, NABARD, SIDBI", "NSIC, DIC, SIDBI, NABARD", "NSIC, DIC, NABARD, SIDBI", "NSIC, NABARD, DIC, SIDBI"], answer: 2, explain: "NSIC (1955), DIC (1978), NABARD (1982), SIDBI (1990).", level: 3 }
    ],
    written: [
      { q: "Define entrepreneurship.", a: "Entrepreneurship is the process of setting up one's own business, as distinct from taking up employment or a profession. The person is the entrepreneur and the business created is the enterprise.", marks: 1 },
      { q: "What is meant by crowdfunding?", a: "Crowdfunding is a way of raising money in which many people each contribute small amounts, usually online.", marks: 1 },
      { q: "State any two problems faced by small businesses.", a: "1. Shortage of finance.\n2. Irregular supply of raw materials. (Also: lack of managerial skills, weak marketing, poor quality, outdated technology, sickness, global competition.)", marks: 2 },
      { q: "State any two functions of District Industries Centres.", a: "1. They identify entrepreneurs and help them prepare project reports.\n2. They arrange credit, raw materials and marketing support, especially in rural and backward areas, through a single window at the district level.", marks: 2 },
      { q: "Explain the role of small business in India with any three points.", a: "1. Employment: small industries are the second largest employer in India after agriculture.\n2. Exports: they contribute substantially to India's exports.\n3. Balanced regional development: they can be set up in villages and small towns. (Also: opportunities for entrepreneurship; low costs from local resources; quick decisions and personal relations.)", marks: 3 },
      { q: "Explain any three characteristics of entrepreneurship.", a: "1. Systematic activity: it requires purposeful, organised effort and can be learnt.\n2. Innovation: the entrepreneur creates value through new ideas.\n3. Risk taking: the entrepreneur bears the risk of the venture. (Also: lawful and purposeful; organisation of production by combining land, labour and capital.)", marks: 3 },
      { q: "Explain the action plan of Startup India.", a: "Startup India was launched on 16 January 2016 to build an ecosystem for startups. Its action plan rests on three pillars:\n1. Simplification and handholding: easier procedures and guidance for startups.\n2. Funding support and incentives.\n3. Industry-academia partnership and incubation.", marks: 3 },
      { q: "Explain any five problems of small businesses in India.", a: "1. Finance: shortage of funds for starting and running the business.\n2. Raw materials: irregular supply and difficulty in getting good quality material.\n3. Managerial skills: lack of trained managers.\n4. Marketing: weak marketing and difficulty in reaching customers.\n5. Technology and capacity utilisation: outdated technology and low use of capacity. (Also: poor quality, sickness, global competition.)", marks: 5 },
      { q: "Explain the different ways of funding a startup.", a: "1. Bootstrapping: the founder uses personal savings and early revenue.\n2. Crowdfunding: many people each contribute a small amount, usually online.\n3. Angel investors: wealthy individuals invest in early-stage startups for a share of ownership.\n4. Venture capital: professionally managed funds invest in high-growth startups for equity.\n5. Business incubators and accelerators, and microfinance institutions and NBFCs, also support startups.", marks: 5 },
      { q: "Case study: Anita Foods makes pickles in a small unit. Its investment in plant and machinery is ₹8 crore and its annual turnover is ₹40 crore. Anita wants a single place at the district level to get her project report prepared, to arrange raw material and to find buyers. She also wants machinery on easy hire-purchase terms.\n(i) Classify Anita Foods under the 2020 limits.\n(ii) Name the institution that gives a single window at the district level.\n(iii) Name the institution that supplies machinery on easy hire-purchase terms.", a: "(i) Under the 2020 limits a small enterprise has investment up to ₹10 crore and turnover up to ₹50 crore. Anita Foods (₹8 crore and ₹40 crore) is above the micro limits (₹1 crore and ₹5 crore) and within the small limits, so it is a small enterprise.\n(ii) District Industries Centre (DIC), launched on 1 May 1978, which helps prepare project reports and arranges credit, raw materials and marketing support.\n(iii) National Small Industries Corporation (NSIC), set up in 1955.", marks: 4, type: "case" }
    ]
  },
  "internal-trade": {
    mcq: [
      { q: "Internal trade means buying and selling of goods and services:", options: ["between two or more countries", "within the boundaries of a nation", "only through retail shops", "only for export purposes"], answer: 1, explain: "Internal trade is trade within the boundaries of a nation. Payment is made in the national currency and no customs duty is charged.", level: 1 },
      { q: "Retail trade involves selling goods:", options: ["in large quantities to other retailers", "to foreign buyers", "to industrial users only", "in small quantities to the ultimate consumers"], answer: 3, explain: "Retailers sell in small quantities to the ultimate consumers. Wholesalers sell in larger lots to retailers or industrial users.", level: 1 },
      { q: "GST was introduced in India on:", options: ["1 July 2017", "16 January 2016", "1 January 1995", "1 May 1978"], answer: 0, explain: "GST was introduced on 1 July 2017 through the 101st Constitutional Amendment Act, 2016.", level: 1 },
      { q: "On inter-state supplies of goods and services, the tax levied under GST is:", options: ["CGST", "SGST", "IGST", "UTGST"], answer: 2, explain: "On inter-state supplies the Centre levies IGST. CGST and SGST apply to supplies within a state.", level: 1 },
      { q: "The GST Council is chaired by the:", options: ["Prime Minister", "Governor of the RBI", "Chief Minister of a state", "Union Finance Minister"], answer: 3, explain: "The GST Council is chaired by the Union Finance Minister, with state finance ministers as members.", level: 1 },

      {
        q: "Assertion (A): Wholesalers help manufacturers to produce on a large scale.\nReason (R): Wholesalers buy goods in bulk from manufacturers.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "Because wholesalers buy in bulk, manufacturers are assured of sales and can plan large-scale production.", level: 2, keepOrder: true
      },
      { q: "Metro Bazaar sells clothes, groceries, furniture and electronics in separate departments under one roof at a central location. It is a:", options: ["Chain store", "Departmental store", "Street trader", "Single-line store"], answer: 1, explain: "A wide variety of products grouped into well-defined departments under one roof, usually at a central location, describes a departmental store.", level: 2 },
      { q: "Sunder carries cloth on his head and sells it from door to door, with no fixed place of business. He is a:", options: ["Market trader", "Cheap jack", "Peddler or hawker", "Speciality store owner"], answer: 2, explain: "Peddlers and hawkers are itinerant retailers who carry goods on bicycles, handcarts or their heads and move from place to place.", level: 2 },
      { q: "Which of the following is a feature of chain stores?", options: ["A wide range of products with maximum services", "Standardised products sold at uniform prices", "Each shop buys independently from different suppliers", "Located only at the central business district"], answer: 1, explain: "Chain stores sell standardised products at uniform prices, with buying done centrally at the head office. Wide ranges and maximum services are features of departmental stores.", level: 2 },
      { q: "Which of the following taxes was NOT among the taxes replaced by GST?", options: ["Service tax", "Central sales tax", "Income tax", "Entry tax"], answer: 2, explain: "GST replaced central excise duty, service tax, VAT, central sales tax and entry tax. Income tax is a direct tax and continues.", level: 2 },

      { q: "A manufacturer buys raw material for ₹50,000 and pays GST at 18%. He sells the finished goods for ₹80,000 and charges GST at 18% on the sale. Using input tax credit, the GST he must pay to the government is:", options: ["₹14,400", "₹9,000", "₹5,400", "₹23,400"], answer: 2, explain: "GST collected on sales = 18% of ₹80,000 = ₹14,400. GST paid on purchases = 18% of ₹50,000 = ₹9,000. Tax payable = ₹14,400 − ₹9,000 = ₹5,400.", level: 3 },
      {
        q: "Assertion (A): Departmental stores provide only limited services and sell for cash only.\nReason (R): A departmental store provides maximum services to its customers.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 3, explain: "A is false: departmental stores offer maximum services and may give credit to regular customers. R is true.", level: 3, keepOrder: true
      },
      { q: "Store X has many identical-looking branches in populous localities, buys centrally at its head office and sells mainly for cash at uniform prices. Store Y has many departments under one roof at a central location, gives maximum services and credit to some regular customers. Which statement is correct?", options: ["X is a departmental store and Y is a chain store", "X is a chain store and Y is a departmental store", "Both X and Y are chain stores", "Both X and Y are departmental stores"], answer: 1, explain: "The features of X (identical branches, central buying, uniform prices, cash sales) are those of a chain store. The features of Y are those of a departmental store.", level: 3 },
      { q: "Vaishali Traders in Surat sells goods to a dealer in Pune and also to a dealer in Vadodara (Gujarat). Which GST applies to these sales?", options: ["Pune: IGST, levied by the Centre; Vadodara: CGST by the Centre and SGST by the state", "Pune: CGST and SGST; Vadodara: IGST", "Both sales: IGST", "Pune: SGST only; Vadodara: CGST only"], answer: 0, explain: "The Pune sale is inter-state, so the Centre levies IGST. The Vadodara sale is within the state, so the Centre levies CGST and the state levies SGST.", level: 3 }
    ],
    written: [
      { q: "What is meant by wholesale trade?", a: "Wholesale trade means buying goods in large quantities from producers and selling them in smaller lots to retailers or industrial users.", marks: 1 },
      { q: "What is Goods and Services Tax (GST)?", a: "GST is a comprehensive, multi-stage, destination-based indirect tax levied on every value addition. It was introduced on 1 July 2017.", marks: 1 },
      { q: "State any two services of wholesalers to manufacturers.", a: "1. They buy in bulk, which helps manufacturers to produce on a large scale.\n2. They bear risks such as fall in prices, theft and spoilage by holding stock in their own name. (Also: financial assistance, expert advice, marketing help, storage.)", marks: 2 },
      { q: "State any two limitations of departmental stores.", a: "1. Lack of personal attention to customers.\n2. High operating cost, which leads to high prices. (Also: risk of loss; inconvenient location for distant customers.)", marks: 2 },
      { q: "Distinguish between departmental stores and chain stores on any three points.", a: "1. Range of products: a departmental store offers a wide variety in departments; a chain store has a limited range of standardised products.\n2. Services: a departmental store provides maximum services; a chain store provides fewer services.\n3. Credit and prices: a departmental store may give credit to regular customers; a chain store sells mainly for cash at uniform prices. (Also: location, central versus populous localities.)", marks: 3 },
      { q: "Explain any three services of retailers to consumers.", a: "1. Regular availability of products near the consumer.\n2. Information about new products, and a wide selection to choose from.\n3. After-sales service and credit to regular customers. (Also: convenience in buying.)", marks: 3 },
      { q: "Explain any three types of itinerant retailers.", a: "Itinerant retailers have no fixed place of business and move from place to place.\n1. Peddlers and hawkers carry goods on bicycles, handcarts or their heads.\n2. Market traders open shops at different places on fixed days, e.g. weekly markets.\n3. Street traders (pavement vendors) sell common-use items at busy places. (Cheap jacks have shops of a temporary nature and move when business is dull.)", marks: 3 },
      { q: "Explain the services rendered by wholesalers to manufacturers and to retailers.", a: "To manufacturers:\n1. Large-scale production: they buy in bulk.\n2. Risk bearing: they hold stock in their own name and bear risks such as fall in prices, theft and spoilage.\n3. Financial assistance by paying cash; expert advice on customer tastes; marketing help and storage.\nTo retailers:\n4. Availability of goods and marketing support.\n5. Credit, specialised knowledge of products, and sharing of risk by supplying in small lots.", marks: 5 },
      { q: "Explain the main features of Goods and Services Tax.", a: "1. It is a comprehensive, multi-stage, destination-based indirect tax levied on every value addition.\n2. It was introduced on 1 July 2017 through the 101st Constitutional Amendment Act, 2016.\n3. It is a dual GST: within a state the Centre levies CGST and the state levies SGST (UTGST in Union Territories); on inter-state supplies the Centre levies IGST.\n4. It replaced taxes such as central excise duty, service tax, VAT, central sales tax and entry tax, moving towards 'one nation, one tax'.\n5. Input tax credit lets a business set off tax paid on purchases against tax on sales, removing the cascading effect. The GST Council, chaired by the Union Finance Minister, recommends rates and rules; registration, returns and payments are online.", marks: 5 },
      { q: "Case study: Priya Mart is a large store in the city centre with separate sections for clothes, kitchenware, toys and groceries, and it gives credit to some regular customers. Its owner plans to open identical small shops, all selling standardised goods at the same prices for cash, with purchases made centrally at the head office. Purchases of ₹1,00,000 carry GST of ₹18,000, and sales of ₹1,50,000 carry GST of ₹27,000.\n(i) Identify the type of retailer Priya Mart is now.\n(ii) Name the type of retail organisation she plans to add and state one advantage.\n(iii) Calculate the GST payable using input tax credit.", a: "(i) A departmental store: many departments under one roof at a central location, with services such as credit to regular customers.\n(ii) A chain store (multiple shop). Advantages: economies of scale from central buying, no middlemen, no bad debts because sales are for cash, and diffusion of risk (any one).\n(iii) GST payable = GST on sales − GST on purchases (input tax credit) = ₹27,000 − ₹18,000 = ₹9,000.", marks: 4, type: "case" }
    ]
  },
  "international-business": {
    mcq: [
      { q: "In licensing, the fee paid by the licensee to the licensor for using its patents, trademarks or technology is called:", options: ["Royalty", "Freight", "Customs duty", "Dividend"], answer: 0, explain: "The licensee pays the licensor a fee called royalty.", level: 1 },
      { q: "The headquarters of the World Trade Organization (WTO) is in:", options: ["New York", "Paris", "London", "Geneva"], answer: 3, explain: "The WTO has its headquarters in Geneva. It was set up on 1 January 1995 as the successor to GATT.", level: 1 },
      { q: "The main document on the basis of which customs permits the export of goods is the:", options: ["Bill of entry", "Shipping bill", "Letter of credit", "Indent"], answer: 1, explain: "The shipping bill is the main export document on the basis of which customs permits export. The bill of entry is filled by the importer.", level: 1 },
      { q: "The bill of entry is a form filled by the:", options: ["exporter, for assessment of export duty", "shipping company, to acknowledge goods", "importer, for assessment of customs duty", "bank, to guarantee payment"], answer: 2, explain: "The importer fills the bill of entry for assessment of customs duty on imported goods.", level: 1 },
      { q: "The Import Export Code (IEC) required by an exporter is obtained from the:", options: ["DGFT", "RBI", "WTO", "GST Council"], answer: 0, explain: "The exporter obtains the IEC from the Directorate General of Foreign Trade (DGFT).", level: 1 },

      { q: "Bharat Herbal, an Indian firm, allows a firm in Nepal to use its patented formula and brand name in return for a fee. This mode of entry into international business is:", options: ["Exporting", "Contract manufacturing", "Licensing", "Wholly owned subsidiary"], answer: 2, explain: "Letting a foreign firm use patents, trademarks or technology for a fee (royalty) is licensing.", level: 2 },
      {
        q: "Assertion (A): International business is wider than international trade.\nReason (R): International business also covers services, investment, licensing and franchising.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 0, explain: "International trade deals with the exchange of goods, while international business also includes services, investment, licensing and franchising. R explains A.", level: 2, keepOrder: true
      },
      { q: "After the cargo of Gujarat Ceramics was loaded on the ship, the ship's commanding officer issued a receipt for it. This document is the:", options: ["Bill of lading", "Mate's receipt", "Shipping bill", "Certificate of origin"], answer: 1, explain: "The mate's receipt is issued by the ship's commanding officer when the cargo is loaded on board.", level: 2 },
      { q: "The importer's bank hands over the shipping documents to the importer only against payment of a sight draft. This arrangement is known as:", options: ["D/A (documents against acceptance)", "Letter of credit", "Indent", "D/P (documents against payment)"], answer: 3, explain: "D/P means documents against payment and is used with a sight draft. D/A is used with a usance (time) draft.", level: 2 },
      { q: "The World Trade Organization was established on 1 January 1995 as the successor to:", options: ["IMF", "GATT", "World Bank", "RBI"], answer: 1, explain: "The WTO succeeded GATT (the General Agreement on Tariffs and Trade), which had been in force since 1948.", level: 2 },

      { q: "Which is the correct sequence of these export documents and steps?", options: ["Mate's receipt, shipping bill, bill of lading, securing payment", "Shipping bill, bill of lading, mate's receipt, securing payment", "Bill of lading, mate's receipt, shipping bill, securing payment", "Shipping bill, mate's receipt, bill of lading, securing payment"], answer: 3, explain: "Customs clearance is obtained with the shipping bill, then the mate's receipt is issued after loading, then freight is paid and the bill of lading is received, and finally payment is secured.", level: 3 },
      {
        q: "Assertion (A): A wholly owned subsidiary involves the lowest investment and risk among the modes of entry.\nReason (R): In a wholly owned subsidiary the parent firm owns 100% and has full control.",
        options: ["Both A and R are true, and R is the correct explanation of A.", "Both A and R are true, but R is not the correct explanation of A.", "A is true, but R is false.", "A is false, but R is true."],
        answer: 3, explain: "A is false: a wholly owned subsidiary needs the highest investment and carries the highest risk. R is true.", level: 3, keepOrder: true
      },
      { q: "Nirmal Auto of Pune and a Japanese firm jointly set up a plant in Pune, with ownership shared between them. The mode of entry used is:", options: ["Joint venture", "Franchising", "Contract manufacturing", "Exporting"], answer: 0, explain: "A foreign firm and a local firm sharing ownership of a business is a joint venture.", level: 3 },
      { q: "An exporter will ship goods to a foreign buyer only if the buyer's bank guarantees to honour the exporter's bills up to a stated amount. The document that gives this guarantee is the:", options: ["Proforma invoice", "Letter of credit", "Bill of lading", "Certificate of origin"], answer: 1, explain: "A letter of credit is a guarantee by the importer's bank to honour the exporter's bills up to a certain amount.", level: 3 }
    ],
    written: [
      { q: "What is meant by international business?", a: "International business means manufacturing and trade beyond the boundaries of one's own country. It is wider than international trade, as it also covers services, investment, licensing and franchising.", marks: 1 },
      { q: "What is a wholly owned subsidiary?", a: "It is a mode of entry in which the parent firm owns 100% of the foreign business and has full control, but bears the highest investment and risk.", marks: 1 },
      { q: "State any two benefits of international business to nations.", a: "1. It helps the nation earn foreign exchange.\n2. It leads to more efficient use of resources, better growth and employment and a higher standard of living.", marks: 2 },
      { q: "Distinguish between licensing and franchising.", a: "1. Licensing: a licensor lets a foreign firm use its patents, trademarks or technology for a fee called royalty.\n2. Franchising is similar but is used for services, e.g. fast-food chains.", marks: 2 },
      { q: "Distinguish between D/P and D/A on any three points.", a: "1. Meaning: D/P means documents against payment; D/A means documents against acceptance.\n2. Draft used: D/P is used with a sight draft; D/A is used with a usance (time) draft.\n3. Release of documents: under D/P the importer gets the documents on paying the bill; under D/A the importer gets them on accepting the bill.", marks: 3 },
      { q: "Explain any three modes of entry into international business.", a: "1. Exporting and importing: the simplest mode, with the least investment and risk.\n2. Contract manufacturing: a firm contracts local producers abroad to make goods or components to its specifications.\n3. Joint venture: a foreign firm and a local firm share ownership of a business. (Others: licensing and franchising, wholly owned subsidiary.)", marks: 3 },
      { q: "State any three objectives of the World Trade Organization.", a: "1. To raise standards of living and ensure full employment and growth of real income and effective demand.\n2. To expand production and trade in goods and services.\n3. To ensure optimal use of world resources with sustainable development, and a fair share of growth in world trade for developing countries.", marks: 3 },
      { q: "Explain the steps in the export procedure.", a: "1. Enquiry and quotation: the exporter receives an enquiry and sends a quotation (proforma invoice); then the order or indent is received.\n2. Creditworthiness and letter of credit: the importer's creditworthiness is checked and a letter of credit is asked for.\n3. Registration: the exporter obtains an Import Export Code (IEC) from the DGFT.\n4. Pre-shipment finance, production or purchase of goods, pre-shipment inspection and certificate of origin.\n5. Shipping and customs: reserve shipping space (shipping order), pack and forward, insure the goods and get customs clearance with the shipping bill.\n6. After loading, obtain the mate's receipt; pay freight and receive the bill of lading.\n7. Prepare the invoice and secure payment by sending documents through a bank.", marks: 5 },
      { q: "Explain the steps in the import procedure.", a: "1. Trade enquiry: collect information about exporters and their terms.\n2. Import licence/IEC: obtain it, and arrange foreign exchange through a bank.\n3. Order (indent): place the order with the exporter.\n4. Letter of credit: send it through the bank and arrange finance to pay for the goods.\n5. Shipment advice: received from the exporter.\n6. Retirement of import documents: pay (D/P) or accept (D/A) the bill of exchange.\n7. Arrival of goods and customs clearance: file the bill of entry, pay customs duty and obtain the delivery order.", marks: 5 },
      { q: "Case study: Jaipur Handicrafts receives a written order, called an indent, from a firm in Dubai. The Dubai firm's bank has given a guarantee to honour the exporter's bills up to ₹20 lakh. Jaipur Handicrafts has not exported before, so it needs a code for foreign trade. After the goods are loaded on the ship, the ship's commanding officer gives a receipt, and later the shipping company issues a document acknowledging goods on board.\n(i) Name the document that is the bank's guarantee.\n(ii) Which code must the firm obtain and from which authority?\n(iii) Name the two documents issued after loading.", a: "(i) Letter of credit: a guarantee by the importer's bank to honour the exporter's bills up to a certain amount.\n(ii) The Import Export Code (IEC), obtained from the Directorate General of Foreign Trade (DGFT).\n(iii) The mate's receipt, issued by the ship's commanding officer when the cargo is loaded on board, and the bill of lading, issued by the shipping company acknowledging goods on board and promising to deliver them (it is a document of title).", marks: 4, type: "case" }
    ]
  }
});
